using AcxiomCRM.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System.Text;
namespace AcxiomCRM.Controllers;
[Authorize] public class ReportsController:Controller {private readonly ApplicationDbContext _db;public ReportsController(ApplicationDbContext db){_db=db;} public IActionResult Index()=>View();
 public async Task<IActionResult> CustomersCsv(){var rows=await _db.Customers.OrderBy(x=>x.CustomerName).Select(x=>new{x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.Status,x.CreatedDate}).ToListAsync();var sb=new StringBuilder("Code,Name,Email,Phone,Company,Status,CreatedDate\n");foreach(var x in rows)sb.AppendLine($"{Esc(x.CustomerCode)},{Esc(x.CustomerName)},{Esc(x.Email)},{Esc(x.Phone)},{Esc(x.CompanyName)},{Esc(x.Status)},{x.CreatedDate:O}");return File(Encoding.UTF8.GetBytes(sb.ToString()),"text/csv","customers-report.csv");} private static string Esc(string? s)=>"\""+(s??"").Replace("\"","\"\"")+"\""; }
